def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    colors=[c for c in Counter(v for row in grid for v in row) if c!=0]
    if len(colors)<2: return grid
    # Outer color is the one with largest bounding box; inner is the other color.
    boxes={}
    for c in colors:
        pts=[(r,col) for r,row in enumerate(grid) for col,v in enumerate(row) if v==c]
        boxes[c]=(min(r for r,col in pts),max(r for r,col in pts),min(col for r,col in pts),max(col for r,col in pts))
    outer=max(colors,key=lambda c:(boxes[c][1]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][2]+1))
    inner=next(c for c in colors if c!=outer)
    a,b,left,right=boxes[outer]; x,y,lo,hi=boxes[inner]
    thick=min(x-a,b-y,lo-left,right-hi)
    out=[row[:] for row in grid]
    for r in range(max(0,a-thick),min(h,b+thick+1)):
        for c in range(max(0,left-thick),min(w,right+thick+1)):
            if out[r][c]==0: out[r][c]=inner
    return out

