def mkgrid(h,w,outer_box,outer_color,inner_box,inner_color):
    g=[[0]*w for _ in range(h)]
    a,b,c,d=outer_box; x,y,z,q=inner_box
    for r in range(a,b+1):
        for j in range(c,d+1): g[r][j]=outer_color
    for r in range(x,y+1):
        for j in range(z,q+1): g[r][j]=inner_color
    return g
